# Scan notebooks for groups of adjacent untagged code cells; list notebooks no record links to.
import glob, json, sys
nb_dir, analysis_dir = sys.argv[1], sys.argv[2]
records = "".join(open(r).read() for r in glob.glob(analysis_dir + "/*.md"))
for path in sorted(glob.glob(nb_dir + "/**/*.ipynb", recursive=True)):
    if path not in records:
        print("NOTEBOOK WITHOUT RECORD:", path)
    cells = json.load(open(path))["cells"]
    group = []
    for i, c in enumerate(cells + [None]):
        untagged = c is not None and c["cell_type"] == "code" and not c["metadata"].get("tags")
        if untagged:
            group.append(i)
        elif group:
            print(path, "untagged cells", group)
            for j in group:
                print("--- src:", "".join(cells[j]["source"]))
                for o in cells[j].get("outputs", []):
                    print("--- out:", o.get("data", {}).get("text/plain", o.get("text", "")))
            group = []
EOF
